import{b as D,j as e,M as q,g as h,I as M,s as w,aV as C,be as p,bf as y,bg as g,bh as v,bi as d,bj as f,bk as b,bl as E,bm as I,bn as x,bo as i,bp as T,bq as A,br as r,bs as j,R as $,h as U,bt as F}from"./index-Cz2wWhgY.js";import"./vendor-DDxydHEc.js";function Y({isOpen:S,onClose:_,language:l="en-US"}){const R=l==="pt-BR",a=(t,n)=>R?t:n,[O,k]=D.useState(null),s=C,[,,c]=I,u=Math.round(F*d),m=U.length,o={...w,margin:0},N=[{id:"evolve",title:a("Como ele evolui","How it evolves"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a("Dia perfeito = você cumpriu a meta do dia e a energia dele fechou cheia. A meta é o que você cadastrou, até o requisito do estágio.","A perfect day = you met your daily goal and its energy ended full. The goal is what you registered, capped at your stage requirement.")}),e.jsx("p",{style:o,children:a(`Rookie→Champion pede ${s.rookie.daysToEvolve} dias perfeitos; Champion→Ultimate ${s.champion.daysToEvolve}; Ultimate→Mega ${s.ultimate.daysToEvolve}; Mega→Ultra ${s.mega.daysToEvolve}.`,`Rookie→Champion needs ${s.rookie.daysToEvolve} perfect days; Champion→Ultimate ${s.champion.daysToEvolve}; Ultimate→Mega ${s.ultimate.daysToEvolve}; Mega→Ultra ${s.mega.daysToEvolve}.`)}),e.jsx("p",{style:o,children:a("Dias perfeitos só acumulam. A evolução é sua: toque no Soulmon na página de Evolução para travar ou destravar o cadeado.","Perfect days only accumulate. Evolution is yours to trigger: tap your Soulmon on the Evolution page to lock or unlock the padlock.")})]})},{id:"hearts",title:a("Corações","Hearts"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`Na virada do dia você perde no máximo ${p} coração, proporcional ao que ficou por fazer. Cumpriu a meta, não perde nada.`,`At the day turn you lose at most ${p} heart, in proportion to what you left undone. Meet the goal and you lose nothing.`)}),e.jsx("p",{style:o,children:a(`Sumiu por ${y} dias ou mais? Voltar não custa nada. Toda segunda ele recupera ${g} coração.`,`Away for ${y} days or more? Coming back costs nothing. Every Monday it recovers ${g} of a heart.`)}),e.jsx("p",{style:o,children:a("Cocô não limpo drena 1 coração a cada 6 horas — dê banho. Esfregar o pet é o principal jeito de curar (até 1 coração por dia). Se zerar, ele regride uma forma.","Uncleaned poop drains 1 heart every 6 hours — give it a bath. Rubbing your pet is the main way to heal (up to 1 heart a day). At zero it degenerates one form.")})]})},{id:"care",title:a("Comida e energia","Food and energy"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`As barras de energia são o requisito do estágio (Rookie: ${s.rookie.required}). Ela enche só comendo e zera todo dia.`,`Energy bars equal your stage requirement (Rookie: ${s.rookie.required}). It fills only by feeding and resets daily.`)}),e.jsx("p",{style:o,children:a(`Cada tarefa concluída rende uma comida. Alimentar dá energia e pontos de atributo — que definem o galho da evolução — e NÃO cura coração. Até ${v} vezes por hora.`,`Each completed task yields one food. Feeding grants energy and attribute points — which steer your evolution branch — and does NOT heal hearts. Up to ${v} times an hour.`)})]})},{id:"habits",title:a("Hábitos","Habits"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`Não existe sequência que zera. O que aparece é a constância: "${u} das últimas ${d}". Uma falta custa uma fatia, nunca tudo.`,`There is no streak that resets. What you see is consistency: "${u} of the last ${d}". A missed day costs a slice, never everything.`)}),e.jsx("p",{style:o,children:a(`A cada ${f} dias de boa constância você ganha um escudo (até ${b}). Ele é gasto sozinho no dia em que você falta — nada para lembrar de ativar.`,`Every ${f} days of good consistency you earn a shield (up to ${b}). It is spent automatically on a day you miss — nothing to remember to switch on.`)}),e.jsx("p",{style:o,children:a(`Uma falta não gera nada. Em ${E} seguidas, o pet oferece uma versão bem menor do hábito — aceitar já conta como feito. E o ícone amadurece até virar árvore em ${c} dias feitos, rendendo mais atributo.`,`One miss does nothing. At ${E} in a row, your pet offers a much smaller version of the habit — accepting counts as done. And the icon matures into a tree at ${c} days done, yielding more attribute.`)})]})},{id:"tasks",title:a("Tarefas","Tasks"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`Toda tarefa tem um esforço: Rápida (1), Média (2) ou Projeto (3). A meta soma esforço, não itens — um Projeto vale três Rápidas. Passando de ${x} pontos no dia, o pet avisa. É aviso, nunca bloqueio.`,`Every task has an effort: Quick (1), Medium (2) or Project (3). The goal adds up effort, not items — one Project is worth three Quick ones. Past ${x} points in a day your pet says so. A heads-up, never a block.`)}),e.jsx("p",{style:o,children:a(`No check-in você escolhe até ${i} focos do dia; completar os ${i} rende o selo.`,`At check-in you pick up to ${i} focus tasks; completing all ${i} earns the seal.`)}),e.jsx("p",{style:o,children:a(`Parada há ${T} dias ela fica assombrada — e concluir uma assombrada dá bônus de alívio. Adiada ${A} vezes, o pet oferece dividir, encolher ou deixar pra lá.`,`Untouched for ${T} days it becomes haunted — and clearing a haunted task grants a relief bonus. Postponed ${A} times, your pet offers to split it, shrink it or let it go.`)}),e.jsx("p",{style:o,children:a('"Algum dia" é permissão formal para não fazer agora: não conta na meta e não assombra. "Deixar pra lá" é um fim honesto, com volta atrás.',`"Someday" is formal permission not to do it now: it doesn't count toward the goal and never haunts. "Let it go" is an honest ending, with an undo.`)})]})},{id:"rest",title:a("Descanso e sonhos","Rest and dreams"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`Você escolhe a SUA janela de sono (padrão ${r.start}–${r.end}, com ${j} min de tolerância). O que conta é o gesto de deitar no horário — nunca a qualidade do seu sono.`,`You choose YOUR own sleep window (default ${r.start}–${r.end}, with ${j} min of grace). What counts is going to bed on time — never how well you slept.`)}),e.jsx("p",{style:o,children:a(`Sem nota de sono e sem castigo: noite sem registro é neutra. A leitura é quantas das últimas ${$} noites entraram na janela.`,`No sleep score and no penalty: an unlogged night is neutral. The reading is how many of the last ${$} nights landed inside the window.`)}),e.jsx("p",{style:o,children:a(`Cada noite na janela ele SONHA, e o sonho é uma cena colecionável dele mesmo — ${m} para descobrir. A raridade vem da regularidade, nunca de dormir mais.`,`Every night inside the window it DREAMS, and the dream is a collectible scene of itself — ${m} to discover. Rarity comes from regularity, never from sleeping longer.`)})]})},{id:"more",title:a("O resto, em uma linha cada","Everything else, one line each"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a("Galhos: Vírus, Dado e Vacina — os requisitos são iguais nos três. No empate decide o seu ritmo de cuidado, e nenhum ritmo é melhor.","Branches: Virus, Data and Vaccine — requirements are identical across all three. Ties are decided by your care rhythm, and no rhythm is better.")}),e.jsx("p",{style:o,children:a("Traço de nascimento: todo Soulmon nasce com um (veja em Estatísticas). Todos são positivos.","Birth trait: every Soulmon is born with one (see it in Stats). All of them are upsides.")}),e.jsx("p",{style:o,children:a("Masmorra e Torneio nunca cobram corações. Perder custa só a run.","Dungeon and Tournament never cost hearts. Losing only costs the run.")}),e.jsx("p",{style:o,children:a("O check-in e o relatório do dia levam vinte segundos; o de domingo descreve a semana. Nada disso vira nota.","Check-in and the daily report take twenty seconds; Sunday describes the week. None of it becomes a score.")}),e.jsx("p",{style:o,children:a("Toda segunda e todo dia 1 vem um recomeço: zera as cobranças pendentes e não apaga nada do que você conquistou.","Every Monday and every 1st a fresh start is offered: pending nagging is cleared and nothing you earned is erased.")})]})}];return e.jsxs(q,{open:S,onClose:_,language:l,title:a("Guia","Guide"),maxWidth:520,children:[e.jsx("p",{style:h,children:a("Toque num assunto. Nada aqui é obrigatório saber para jogar.","Tap a topic. None of this is required knowledge to play.")}),e.jsx("div",{style:{display:"flex",flexDirection:"column"},children:N.map(t=>{const n=O===t.id;return e.jsxs("div",{style:{borderTop:"1px solid var(--sm2-line)"},children:[e.jsxs("button",{type:"button",onClick:()=>k(n?null:t.id),"aria-expanded":n,"aria-controls":`guide-${t.id}`,style:{width:"100%",minHeight:52,display:"flex",alignItems:"center",gap:10,padding:"10px 2px",background:"none",border:"none",cursor:"pointer",textAlign:"left",fontFamily:"var(--sm2-font-display)",fontSize:"var(--sm2-text-md)",fontWeight:600,color:"var(--sm2-ink)"},children:[e.jsx("span",{style:{flex:1},children:t.title}),e.jsx(M,{name:n?"expand_less":"expand_more",size:24,tone:"muted"})]}),n&&e.jsx("div",{id:`guide-${t.id}`,style:{display:"flex",flexDirection:"column",gap:10,padding:"0 2px 16px"},children:t.body})]},t.id)})}),e.jsx("p",{style:{...h,borderTop:"1px solid var(--sm2-line)",paddingTop:16},children:a("Nos dias em que não der, ele continua aqui.","On the days you can’t, it stays right here.")})]})}export{Y as GuideModal};
